void
calc_nu(
  const gkyl_spitzer_coll_freq *up, struct gkyl_range qrange, const double *vtSqSelf_d,
  double vtSqMinSelf, const double *m0Other_d, const double *vtSqOther_d, double vtSqMinOther,
  double normNu, long linidx, struct gkyl_array *nuOut
)
{
  // Perform the multiplication of normNu*n_r/(v_ts^2+v_tr^2)^(3/2) via
  // quadrature in one cell.
  struct gkyl_range_iter qiter;
  gkyl_range_iter_init(&qiter, &qrange);
  while (gkyl_range_iter_next(&qiter)) {
    int qidx = gkyl_range_idx(&qrange, qiter.idx);

    // Evaluate densities and thermal speeds (squared) at quad point.
    const double *b_ord = gkyl_array_cfetch(up->basis_at_ords, qidx);
    double vtSqSelf_q = 0., m0Other_q = 0., vtSqOther_q = 0.;
    for (int k = 0; k < up->num_basis; ++k) {
      vtSqSelf_q += vtSqSelf_d[k] * b_ord[k];
      m0Other_q += m0Other_d[k] * b_ord[k];
      vtSqOther_q += vtSqOther_d[k] * b_ord[k];
    }

    double *fq = gkyl_array_fetch(up->fun_at_ords, qidx);

    if (m0Other_q < 0.) {
      fq[0] = 0.;
    } else if ((vtSqSelf_q < vtSqMinSelf) && (vtSqOther_q < vtSqMinOther)) {
      fq[0] = normNu * m0Other_q / pow(sqrt(vtSqMinSelf + vtSqMinOther), 3);
    } else if (vtSqSelf_q < vtSqMinSelf) {
      fq[0] = normNu * m0Other_q / pow(sqrt(vtSqMinSelf + vtSqOther_q), 3);
    } else if (vtSqOther_q < vtSqMinOther) {
      fq[0] = normNu * m0Other_q / pow(sqrt(vtSqSelf_q + vtSqMinOther), 3);
    } else {
      fq[0] = normNu * m0Other_q / pow(sqrt(vtSqSelf_q + vtSqOther_q), 3);
    }
  }

  // compute expansion coefficients of Maxwellian on basis
  proj_on_basis(up, up->fun_at_ords, gkyl_array_fetch(nuOut, linidx));
}

void
gkyl_spitzer_coll_freq_advance_normnu(
  const gkyl_spitzer_coll_freq *up, const struct gkyl_range *range,
  const struct gkyl_array *momsSelf, double vtSqMinSelf, const struct gkyl_array *momsOther,
  double vtSqMinOther, double normNu, struct gkyl_array *nuOut
)
{
  // Scale project normNu*n_r/(v_ts^2+v_tr^2)^(3/2) onto the basis using
  // quadrature.

#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    return gkyl_spitzer_coll_freq_advance_normnu_cu(
      up, range, momsSelf, vtSqMinSelf, momsOther, vtSqMinOther, normNu, nuOut
    );
  }
#endif

  int vtsq_idx = momsSelf->ncomp - up->num_basis;

  // Create range to loop over quadrature points.
  struct gkyl_range qrange = get_qrange(up->ndim, up->num_quad);

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long linidx = gkyl_range_idx(range, iter.idx);

    const double *momsSelf_d = gkyl_array_cfetch(momsSelf, linidx);
    const double *momsOther_d = gkyl_array_cfetch(momsOther, linidx);

    const double *vtSqSelf_d = &momsSelf_d[vtsq_idx];
    const double *m0Other_d = momsOther_d;
    const double *vtSqOther_d = &momsOther_d[vtsq_idx];

    calc_nu(
      up, qrange, vtSqSelf_d, vtSqMinSelf, m0Other_d, vtSqOther_d, vtSqMinOther, normNu, linidx,
      nuOut
    );
  }
}

void
gkyl_spitzer_coll_freq_advance(
  const gkyl_spitzer_coll_freq *up, const struct gkyl_range *range, const struct gkyl_array *bmag,
  double qSelf, double mSelf, const struct gkyl_array *momsSelf, double vtSqMinSelf, double qOther,
  double mOther, const struct gkyl_array *momsOther, double vtSqMinOther, struct gkyl_array *nuOut
)
{
  // Compute the Spitzer-like collision frequency
  //   nu_sr = nu_frac * (n_r/m_s)*(1/m_s+1/m_r)
  //     * (q_s^2*q_r^2*log(Lambda_sr)/(3*(2*pi)^(3/2)*epsilon_0^2))
  //     * (1/(v_ts^2+v_tr^2)^(3/2))
  // where log(Lambda_sr) is the Coulomb logarithm (see Gkeyll docs).

#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    return gkyl_spitzer_coll_freq_advance_cu(
      up, range, bmag, qSelf, mSelf, momsSelf, vtSqMinSelf, qOther, mOther, momsOther, vtSqMinOther,
      nuOut
    );
  }
#endif

  int vtsq_idx = momsSelf->ncomp - up->num_basis;
  double mReduced = 1. / (1. / mSelf + 1. / mOther);
  double timeConstFac = up->nufraceps0_fac * pow(qSelf * qOther, 2) / (mSelf * mReduced);

  // Create range to loop over quadrature points.
  struct gkyl_range qrange = get_qrange(up->ndim, up->num_quad);

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long linidx = gkyl_range_idx(range, iter.idx);

    const double *bmag_d = gkyl_array_cfetch(bmag, linidx);
    const double *momsSelf_d = gkyl_array_cfetch(momsSelf, linidx);
    const double *momsOther_d = gkyl_array_cfetch(momsOther, linidx);

    const double *m0Self_d = momsSelf_d;
    const double *vtSqSelf_d = &momsSelf_d[vtsq_idx];
    const double *m0Other_d = momsOther_d;
    const double *vtSqOther_d = &momsOther_d[vtsq_idx];

    // Compute the Coulomb logarithm using cell-average values.
    double bmagAv = bmag_d[0] * up->cellav_fac;
    double m0SelfAv = m0Self_d[0] < 0. ? 1.e-14 : m0Self_d[0] * up->cellav_fac;
    double vtSqSelfAv = vtSqSelf_d[0] < vtSqMinSelf ? vtSqMinSelf * up->cellav_fac :
                                                      vtSqSelf_d[0] * up->cellav_fac;
    double m0OtherAv = m0Other_d[0] < 0. ? 1.e-14 : m0Other_d[0] * up->cellav_fac;
    double vtSqOtherAv = vtSqOther_d[0] < vtSqMinOther ? vtSqMinOther * up->cellav_fac :
                                                         vtSqOther_d[0] * up->cellav_fac;

    double omegaSqSumSelf =
      m0SelfAv * pow(qSelf, 2) / (up->eps0 * mSelf) + pow(qSelf * bmagAv / mSelf, 2);
    double omegaSqSumOther =
      m0OtherAv * pow(qOther, 2) / (up->eps0 * mOther) + pow(qOther * bmagAv / mOther, 2);

    double rmaxSumSelf = omegaSqSumSelf / (vtSqSelfAv + 3. * vtSqSelfAv) +
                         omegaSqSumOther / (vtSqOtherAv + 3. * vtSqSelfAv);
    double rmaxSumOther = omegaSqSumSelf / (vtSqSelfAv + 3. * vtSqOtherAv) +
                          omegaSqSumOther / (vtSqOtherAv + 3. * vtSqOtherAv);

    double rmaxSelf = 1. / sqrt(rmaxSumSelf);
    double rmaxOther = 1. / sqrt(rmaxSumOther);

    double uRelSq = 3. * (vtSqOtherAv + vtSqSelfAv);

    double rMin = GKYL_MAX2(
      fabs(qSelf * qOther) * up->r4pieps0_fac / (mReduced * uRelSq),
      up->hbar_fac / (mReduced * sqrt(uRelSq))
    );

    double logLambda =
      0.5 * (0.5 * log(1. + pow(rmaxSelf / rMin, 2)) + 0.5 * log(1. + pow(rmaxOther / rMin, 2)));

    // Normalized nu (nu missing density and temperature factors).
    double normNu = timeConstFac * logLambda;

    calc_nu(
      up, qrange, vtSqSelf_d, vtSqMinSelf, m0Other_d, vtSqOther_d, vtSqMinOther, normNu, linidx,
      nuOut
    );
  }
}

void
gkyl_spitzer_coll_freq_release(gkyl_spitzer_coll_freq *up)
{
  gkyl_array_release(up->weights);
  gkyl_array_release(up->basis_at_ords);
  if (!up->use_gpu) {
    gkyl_array_release(up->fun_at_ords);
  }
  gkyl_free(up);
}
  def _result(self,
              grid,
              values,
              *,
              inplace: bool = False,
              tag: str | None = None,
              label: str | None = None,
              **ctx_updates):
    """The single 'mutate self vs. emit a new dataset' decision point.

    Every verb funnels its computed ``(grid, values)`` through here. Because
    ``copy`` uses ``type(self)``, the result is the *same* (sub)class as the
    input -- so operations preserve the fluent dataset type. New results
    own independent grid arrays and nested metadata.
    """
    target = self if inplace else self.clone(metadata_only=True)
    target.push(grid if inplace else [np.array(g, copy=True) for g in grid],
                values)
    if tag is not None:
      target.set_tag(tag)
    if label is not None:
      target._custom_label = label
    if ctx_updates:
      target.ctx.update(deepcopy(ctx_updates))
    return target

  # ---------------------------------------------------------- operability
  @property
  def is_interpolated(self) -> bool:
    """True when values are safe for element-wise math: data with no DG
    structure at all (no ``basis_type`` -- plain point values by
    construction), never-modal DG data (``value_form`` is ``nodal``/
    ``quad``), or modal data already run through ``interpolate``
    (``ctx['interpolated']``)."""
    if self.ctx.get("interpolated", False):
      return True
    form = self.ctx.get("value_form")
    if form in ("nodal", "quad"):
      return True
    if form == "modal":
      return False
    return not self.ctx.get("basis_type") and self.backend == "numpy"

  def _require_operable(self) -> None:
    """Pointwise math is allowed exactly where the data are point values:
    the NumPy field domain, or the nodal/quad value forms. Modal
    coefficients refuse -- a pointwise operation has no basis-space meaning.
    ``value_form`` applies uniformly regardless of ``backend`` -- it is the
    one fact for "what do these values mean", set once at load time."""
    if self._values is None:
      raise ValueError("GData has no values to operate on.")
    if not self.is_interpolated:
      raise ValueError(
          "Cannot do NumPy math on modal DG coefficients. Convert explicitly: "
          ".represent(to='nodal')/.represent(to='quad') "
          "(pointwise, stays native), .apply(fn) "
          "(pointwise via quadrature, projects back to modal), or .interpolate() "
          "(leave for the NumPy field domain).")

  # ----------------------------------------------------- numpy interop (read)
  _HANDLED_TYPES = (numbers.Number, np.ndarray, np.generic)

"""Use optional native collision and gyrokinetic kernels on loaded GData.

Build with POSTGKYL_GKEYLL_MODULE=gyrokinetic (or pkpm), then generate the
fixtures with python tests/generate_test_data.py before running this script.
A core-only installation prints the build instruction and exits normally.
"""

import numpy as np
import postgkyl as pg
from postgkyl import gpython
from postgkyl.diagnostics.vm.collisions import spitzer_coll_freq
from postgkyl.diagnostics.gk import mom_gyrokinetic
from _example_paths import TEST_DATA


def main():
  modules = gpython.module_api_versions()
  if "gyrokinetic" not in modules:
    print(
        "This example needs POSTGKYL_GKEYLL_MODULE=gyrokinetic at installation."
    )
    return
  generated = TEST_DATA / "generated"
  moms = pg.load(generated / "collision_moms_p1.gkyl")
  bmag = pg.load(generated / "collision_bmag_p1.gkyl")
  nu = spitzer_coll_freq(moms,
                         moms,
                         bmag,
                         mass_self=1.,
                         mass_other=1.,
                         charge_self=-1.,
                         charge_other=1.,
                         epsilon_0=1.,
                         hbar=0.)
  assert np.all(nu.interpolate().values > 0)
  print("Modal collision frequency:", nu)

  distribution = pg.load(generated / "native_gk_1x2v_p1_f.gkyl")
  bmag = pg.load(generated / "native_gk_1x2v_p1_bmag.gkyl")
  density = mom_gyrokinetic(distribution, bmag, mass=2., moment="M0")
  # F=2+x+v, v in [-.5,2.5], mu in [.25,1.75]:
  # (2*pi/m) integral F dv dmu = 4.5*pi*(3+x).
  centers = (density.grid[0][1:] + density.grid[0][:-1]) / 2
  np.testing.assert_allclose(density.values[:, 0],
                             np.sqrt(2) * 4.5 * np.pi * (3 + centers),
                             rtol=3e-14,
                             atol=3e-14)
  print("Modal gyrokinetic density:", density)


if __name__ == "__main__":
  main()
